} from "./types";

const matchers: ToolMatcher[] = [
  matchWebSearch,
  matchSkillActivation,
  matchChainContext,
  matchNativeBalance,
  matchTokenLookup,
  matchLifiSwapPrep,
  matchLifiQuote,
  matchLifiApproval,
  matchStagedTx,
  matchSimulation,
  matchPendingApproval,
  matchEvmCall,
  matchError,
];

const fallbackOperation = (ctx: ToolContext) => {
  const args = asRecord(ctx.parsedArgs);
  const symbol = asString(args?.symbol);
  const facts = uniqueFacts(
    [
      topicTokenFact(ctx.rawLabel),
      chainFact(args?.chain_id, args?.chain_name, "args"),
      symbol ? tokenFact(symbol, "args") : null,
    ].filter((fact): fact is NonNullable<typeof fact> => fact != null),
  );

  const confidence: ToolConfidence = facts.length > 0 ? "medium" : "fallback";

  return {
    id: "fallback",
    facts,
    confidence,
    rawLabel: ctx.rawLabel,
  };
};

export const interpretToolContext = (ctx: ToolContext): InterpretedToolStep => {
  const operation =
    matchers.reduce<ReturnType<ToolMatcher>>(
      (matched, matcher) => matched ?? matcher(ctx),
      null,
    ) ?? fallbackOperation(ctx);

  return presentOperation(operation);
};

import {
  addressFact,
  amountFact,
  asRecord,
  asString,
  chainFact,
  chainFactFromRecord,
  hostnameFromUrl,
  statusFact,
  tokenFact,
  topicTokenFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
  confidence: ToolOperation["confidence"] = "high",
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence,
  rawLabel,
});

const displaySkillLabel = (skillId: string): string | undefined => {
  if (skillId === "lifi_swap") return "Lifi";
  return undefined;
};

export const matchWebSearch: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const body = asString(resultRecord.args) ?? asString(resultRecord.result);
  if (!body || !/Found\s+\d+\s+results/i.test(body)) return null;

  const count = body.match(/Found\s+(\d+)\s+results/i)?.[1];
  const firstUrl = body.match(/URL:\s*(https?:\/\/\S+)/i)?.[1];
  const source = firstUrl ? hostnameFromUrl(firstUrl) : null;

  return op("web.search", rawLabel, [
    topicTokenFact(rawLabel),
    count
      ? { kind: "count", role: "results", value: count, source: "result" }
      : null,
    source ? { kind: "sourceHost", value: source, source: "result" } : null,
  ]);
};

export const matchSkillActivation: ToolMatcher = ({
  rawLabel,
  resultRecord,
}) => {
  if (!resultRecord) return null;
  if (!("activated" in resultRecord || "applied_scope" in resultRecord)) {
    return null;
  }

  const activated = Array.isArray(resultRecord.activated)
    ? resultRecord.activated.filter(
        (value): value is string => typeof value === "string",
      )
    : [];

  return op(
    "skill.activate",
    rawLabel,
    activated.length > 0
      ? activated.map((value) => ({
          kind: "skill",
          value,
          label: displaySkillLabel(value),
          source: "result" as const,
        }))
      : [{ kind: "skill", value: "Skill", source: "result" }],
  );
};

export const matchChainContext: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  if (
    !(
      "supported_chains" in resultRecord ||
      "rpc_endpoint" in resultRecord ||
      "block_number" in resultRecord
    )
  ) {
    return null;
  }

  return op("evm.context", rawLabel, [
    chainFact(resultRecord.chain_id, resultRecord.chain_name),
    typeof resultRecord.block_number === "number"
      ? {
          kind: "block",
          value: String(resultRecord.block_number),
          source: "result",
        }
      : null,
  ]);
};

export const matchNativeBalance: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const address = addressFact(resultRecord.address, "owner");
  const balance = amountFact(resultRecord.balance_eth, "ETH");
  if (!address || !balance) return null;

  return op("evm.account.native_balance", rawLabel, [
    chainFactFromRecord(resultRecord),
    address,
    { ...balance, role: "native" },
  ]);
};

export const matchTokenLookup: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  if (!("found" in resultRecord && "contracts" in resultRecord)) return null;

  const contracts = Array.isArray(resultRecord.contracts)
    ? resultRecord.contracts
        .map(asRecord)
        .filter((item): item is Record<string, unknown> => !!item)
    : [];
  const first = contracts[0];
  const found = resultRecord.found === true;

  return op(`evm.contract.lookup.${found ? "found" : "missing"}`, rawLabel, [
    chainFactFromRecord(first) ?? chainFactFromRecord(resultRecord),
    tokenFact(first?.symbol) ?? topicTokenFact(rawLabel),
  ]);
};

export const matchError: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const rawError = resultRecord.error;
  if (!(resultRecord.is_error === true || rawError)) return null;
  const errorRecord = asRecord(rawError);
  const code =
    asString(resultRecord.code) ??
    asString(errorRecord?.code) ??
    asString(errorRecord?.type);

  return op("tool.error", rawLabel, [
    statusFact("failed"),
    code
      ? { kind: "code", role: "error", value: code, source: "result" }
      : null,
  ]);
};

import { EVM_SELECTOR_REGISTRY } from "@/components/assistant-ui/tool-registry";

import {
  addressFact,
  addressFromWord,
  amountFact,
  asString,
  bigintFromWord,
  calldataWord,
  chainFactFromRecord,
  decodedValue,
  selectorFact,
  topicTokenFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
  confidence: ToolOperation["confidence"] = "high",
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence,
  rawLabel,
});

export const matchEvmCall: ToolMatcher = ({ rawLabel, resultRecord }) => {
  const tx =
    resultRecord && typeof resultRecord.tx === "object"
      ? (resultRecord.tx as Record<string, unknown>)
      : null;
  const input = asString(tx?.input);
  if (!resultRecord || !tx || !input) return null;
  const selector = selectorFact(input);
  if (!selector) return null;

  const selectorMeta = EVM_SELECTOR_REGISTRY[selector.value];
  const firstAddress = addressFromWord(calldataWord(input, 0));
  const secondAddress = addressFromWord(calldataWord(input, 1));
  const secondAmount = bigintFromWord(calldataWord(input, 1));
  const decoded = decodedValue(resultRecord);

  if (selectorMeta?.kind === "erc20_balance") {
    return op("evm.call.erc20.balance_of", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "owner", "decoded"),
    ]);
  }

  if (selectorMeta?.kind === "erc20_metadata") {
    const isDecimals = selectorMeta.name === "decimals";
    return op(
      isDecimals ? "evm.call.erc20.decimals" : "evm.call.erc20.metadata",
      rawLabel,
      [
        chainFactFromRecord(tx),
        topicTokenFact(rawLabel),
        { ...selector, label: selectorMeta.name, role: "metadata" },
        decoded != null
          ? {
              kind: "decoded",
              role: isDecimals ? "decimals" : undefined,
              value: String(decoded),
              label: isDecimals ? `${String(decoded)} decimals` : undefined,
              source: "decoded",
            }
          : null,
      ],
    );
  }

  if (selectorMeta?.kind === "erc20_allowance") {
    return op("evm.call.erc20.allowance", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "owner", "decoded"),
      addressFact(secondAddress, "spender", "decoded"),
    ]);
  }

  if (selectorMeta?.kind === "erc20_approve") {
    return op("evm.call.erc20.approve", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "spender", "decoded"),
      amountFact(secondAmount, undefined, "decoded"),
    ]);
  }

  if (selectorMeta?.kind === "erc20_transfer") {
    return op("evm.call.erc20.transfer", rawLabel, [
      chainFactFromRecord(tx),
      topicTokenFact(rawLabel),
      addressFact(firstAddress, "recipient", "decoded"),
      amountFact(secondAmount, undefined, "decoded"),
    ]);
  }

  return op(
    "evm.call.generic",
    rawLabel,
    [
      chainFactFromRecord(tx),
      addressFact(tx.from, "from"),
      addressFact(tx.to, "to"),
    ],
    "medium",
  );
};

import { EVM_SELECTOR_REGISTRY } from "@/components/assistant-ui/tool-registry";

import {
  asNumber,
  asString,
  chainFact,
  chainFactFromRecord,
  humanize,
  selectorFact,
  statusFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence: "high",
  rawLabel,
});

const stagedActionId = (action: string): string =>
  action
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "") || "custom";

export const matchStagedTx: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord || resultRecord.current_lifecycle !== "queued") {
    return null;
  }

  const data = asString(resultRecord.data);
  const selector = data ? selectorFact(data) : null;
  const selectorMeta = selector ? EVM_SELECTOR_REGISTRY[selector.value] : null;
  const kind = asString(resultRecord.kind);
  const action = selectorMeta?.chip ?? kind;
  const pendingTxId = asNumber(resultRecord.pending_tx_id);

  return op(`evm.tx.stage.${stagedActionId(action ?? "custom")}`, rawLabel, [
    chainFact(resultRecord.chain_id),
    action
      ? {
          kind: "action",
          value: action,
          label: humanize(action),
          source: selectorMeta ? "decoded" : "result",
        }
      : null,
    pendingTxId != null
      ? {
          kind: "count",
          role: "tx",
          value: String(pendingTxId),
          source: "result",
        }
      : null,
    statusFact(resultRecord.current_lifecycle),
  ]);
};

export const matchSimulation: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const sim =
    typeof resultRecord.simulation === "object" && resultRecord.simulation
      ? (resultRecord.simulation as Record<string, unknown>)
      : null;
  if (!(sim || "batch_success" in resultRecord)) return null;

  const batchSuccess =
    (sim?.batch_success ?? resultRecord.batch_success) === true;
  const gas = asNumber(sim?.total_gas) ?? asNumber(resultRecord.total_gas);
  const steps = Array.isArray(sim?.steps) ? sim.steps.length : undefined;

  return op("evm.tx.simulate_batch", rawLabel, [
    chainFactFromRecord(resultRecord) ?? chainFact(undefined, sim?.network),
    steps != null
      ? {
          kind: "count",
          role: "tx",
          value: String(steps),
          source: "result",
        }
      : null,
    statusFact(batchSuccess),
    gas != null
      ? {
          kind: "gas",
          value: String(gas),
          source: "result",
        }
      : null,
  ]);
};

export const matchPendingApproval: ToolMatcher = ({
  rawLabel,
  resultRecord,
}) => {
  if (
    !resultRecord ||
    !(
      resultRecord.status === "pending_approval" ||
      Array.isArray(resultRecord.tx_ids)
    )
  ) {
    return null;
  }

  const txCount = Array.isArray(resultRecord.tx_ids)
    ? resultRecord.tx_ids.length
    : undefined;

  return op("wallet.tx.pending_approval", rawLabel, [
    chainFactFromRecord(resultRecord),
    txCount != null
      ? {
          kind: "count",
          role: "tx",
          value: String(txCount),
          source: "result",
        }
      : null,
    statusFact("pending_approval"),
  ]);
};

import {
  amountFact,
  asRecord,
  asString,
  chainFactFromRecord,
  tokenFact,
  uniqueFacts,
} from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

const op = (
  id: string,
  rawLabel: string,
  facts: Array<ToolFact | null>,
): ToolOperation => ({
  id,
  facts: uniqueFacts(facts.filter((fact): fact is ToolFact => fact != null)),
  confidence: "high",
  rawLabel,
});

const displayAmount = (value: unknown): string | undefined =>
  asString(asRecord(value)?.display);

const amountDisplayFact = (
  value: unknown,
  role: "primary" | "secondary",
): ToolFact | null => {
  const fact = amountFact(displayAmount(value));
  return fact ? { ...fact, role } : null;
};

const amountTextFact = (
  value: unknown,
  role: "primary" | "secondary",
): ToolFact | null => {
  const fact = amountFact(asString(value));
  return fact ? { ...fact, role } : null;
};

const tokenSymbol = (value: unknown): string | undefined =>
  asString(asRecord(value)?.symbol);

const tokenPairFact = (
  fromToken: unknown,
  toToken: unknown,
): ToolFact | null => {
  const fromSymbol = tokenSymbol(fromToken);
  const toSymbol = tokenSymbol(toToken);
  if (!fromSymbol || !toSymbol) return null;
  return {
    kind: "token",
    role: "primary",
    value: `${fromSymbol} -> ${toSymbol}`,
    source: "result",
  };
};

const lifiFact = (): ToolFact => ({
  kind: "sourceHost",
  value: "Lifi",
  source: "result",
});

export const matchLifiQuote: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord) return null;
  const fromToken = asRecord(resultRecord.from_token);
  const toToken = asRecord(resultRecord.to_token);
  const estimate = asRecord(resultRecord.estimate);
  if (!asString(resultRecord.quote_id) || !fromToken || !toToken || !estimate) {
    return null;
  }

  return op("lifi.quote", rawLabel, [
    chainFactFromRecord(resultRecord),
    amountDisplayFact(resultRecord.from_amount, "primary"),
    amountTextFact(estimate.to_amount_display, "secondary"),
    tokenPairFact(fromToken, toToken),
  ]);
};

export const matchLifiApproval: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord || !asString(resultRecord.quote_id)) return null;
  if (!("approval_required" in resultRecord)) return null;

  const approval = asRecord(resultRecord.approval);
  const token = asRecord(approval?.token) ?? asRecord(resultRecord.token);
  if (!token) return null;

  return op("lifi.approval", rawLabel, [
    chainFactFromRecord(resultRecord) ?? chainFactFromRecord(token),
    tokenFact(token.symbol),
    amountDisplayFact(approval?.amount, "primary"),
  ]);
};

export const matchLifiSwapPrep: ToolMatcher = ({ rawLabel, resultRecord }) => {
  if (!resultRecord || !asString(resultRecord.quote_id)) return null;
  const stageTx = asRecord(resultRecord.stage_tx);
  if (stageTx?.kind !== "lifi_swap") return null;

  const estimate = asRecord(resultRecord.estimate);
  return op("lifi.swap.prepare", rawLabel, [
    chainFactFromRecord(resultRecord),
    lifiFact(),
    amountDisplayFact(resultRecord.from_amount, "primary"),
    amountTextFact(estimate?.to_amount_display, "secondary"),
    tokenPairFact(resultRecord.from_token, resultRecord.to_token),
  ]);
};

import { humanize } from "../normalize";
import type { InterpretedToolStep, ToolFact, ToolOperation } from "../types";
import { chipForFact, uniqueChips } from "./chips";
import { descriptorFor, iconForDescriptor } from "./descriptors";

const pickFacts = (
  facts: ToolFact[],
  slots: ReturnType<typeof descriptorFor>["chipPlan"],
): ToolFact[] => {
  const picked: ToolFact[] = [];
  const used = new Set<ToolFact>();

  for (const slot of slots) {
    const matches = facts.filter(
      (fact) =>
        fact.kind === slot.kind &&
        (slot.role == null || fact.role === slot.role) &&
        !used.has(fact),
    );
    const selected = slot.repeat ? matches : matches.slice(0, 1);
    selected.forEach((fact) => {
      picked.push(fact);
      used.add(fact);
    });
  }

  return picked;
};

const statusLast = (facts: ToolFact[]): ToolFact[] => [
  ...facts.filter((fact) => fact.kind !== "status"),
  ...facts.filter((fact) => fact.kind === "status"),
];

export const presentOperation = (
  operation: ToolOperation,
): InterpretedToolStep => {
  const descriptor = descriptorFor(operation);
  const title =
    descriptor.title === "fixed"
      ? (descriptor.fixedTitle ?? humanize(operation.rawLabel))
      : humanize(operation.rawLabel);
  const chips = uniqueChips(
    statusLast(pickFacts(operation.facts, descriptor.chipPlan))
      .map(chipForFact)
      .filter((chip): chip is NonNullable<typeof chip> => chip != null),
  );

  return {
    icon: iconForDescriptor(descriptor, operation),
    title,
    chips,
    confidence: operation.confidence,
    rawLabel: operation.rawLabel,
  };
};

